package com.hostelcare.controller;
import com.hostelcare.dto.ApiDtos.StatusRequest;import com.hostelcare.repository.*;import com.hostelcare.service.ComplaintService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.security.Principal;import java.util.*;
@RestController @RequestMapping("/api/staff") public class StaffController {private final UserRepository users;private final ComplaintRepository complaints;private final AssignmentRepository assignments;private final ComplaintService service;public StaffController(UserRepository u,ComplaintRepository c,AssignmentRepository a,ComplaintService s){users=u;complaints=c;assignments=a;service=s;}
 @GetMapping("/assignments") public List<?> assignments(Principal p){var u=users.findByEmail(p.getName()).orElseThrow();return complaints.findAssigned(u.userId).stream().map(c->{Map<String,Object> m=ViewMapper.complaint(c);m.put("assignment",assignments.findByComplaintComplaintIdAndActiveTrue(c.complaintId).stream().findFirst().map(a->a.assignedAt).orElse(null));return m;}).toList();}
 @GetMapping("/complaints/{id}") public Map<String,Object> get(@PathVariable Long id,Principal p){return ViewMapper.complaint(service.get(id,p.getName()));}
 @PutMapping("/complaints/{id}/status") public Map<String,Object> update(@PathVariable Long id,@Valid @RequestBody StatusRequest r,Principal p){return ViewMapper.complaint(service.updateStatus(id,p.getName(),r,true));}
 @GetMapping("/history") public List<?> history(Principal p){var u=users.findByEmail(p.getName()).orElseThrow();return assignments.findByStaffUserIdOrderByAssignedAtDesc(u.userId).stream().map(a->a.complaint).filter(c->c.status==com.hostelcare.enums.ComplaintStatus.RESOLVED||c.status==com.hostelcare.enums.ComplaintStatus.CLOSED).distinct().map(ViewMapper::complaint).toList();}
}
